import Component from 'flarum/common/Component';
import PollOption from './PollOption';
import ItemList from 'flarum/common/utils/ItemList';
export default class PollOptions extends Component {
  view() {
    return m("div", {
      className: "Poll-options list-layout"
    }, this.pollOptions().toArray());
  }
  pollOptions() {
    const items = new ItemList();
    this.attrs.options.forEach(option => {
      items.add('option' + option.id(), this.createOptionView(option));
    });
    return items;
  }
  createOptionView(option) {
    return m(PollOption, {
      name: this.attrs.name,
      option: option,
      state: this.attrs.state
    });
  }
}
flarum.reg.add('framio-engagement', 'polls/forum/components/Poll/PollOptions', PollOptions);