import Component from 'flarum/common/Component';
import ItemList from 'flarum/common/utils/ItemList';
export default class PollImage extends Component {
  imageUrl = null;
  imageAlt = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.imageUrl = this.attrs.poll.imageUrl();
    this.imageAlt = this.attrs.poll.imageAlt();
  }
  view() {
    if (!this.imageUrl) {
      return;
    }
    return m("div", {
      className: "PollImage"
    }, this.imageItems().toArray());
  }
  imageItems() {
    const items = new ItemList();
    const srcset = this.attrs.poll.imageSrcset();
    items.add('image', m("img", {
      src: this.imageUrl,
      srcset: srcset ?? undefined,
      alt: this.imageAlt ?? '',
      className: "PollImage-image",
      loading: "lazy"
    }));
    return items;
  }
}
flarum.reg.add('framio-engagement', 'polls/forum/components/Poll/PollImage', PollImage);